/* Styles pour les titres des règles par famille */
.rule-title.insuffisance { --color-background: #e7ceec; --color-box: #8605aa; }
.rule-title.tricherie { --color-background: #f8efd0; --color-box: #daaf01; }
.rule-title.erreur-mathematique { --color-background: #cdede8; --color-box: #01a986; }
.rule-title.paralogisme { --color-background: #e1f1cd; --color-box: #69b402; }
.rule-title.influence { --color-background: #ffe6fc; --color-box: #ff66eb; }
.rule-title.detournement-de-la-langue { --color-background: #cad7ea; --color-box: #022cb2; }
.rule-title.obstruction { --color-background: #eed0d0; --color-box: #ab1516; }

/* Style commun pour les titres de règles (h2, h3) */
.rule-title {
    font-size: 0.7em;
    background-color: var(--color-background);
    padding: 0.3em;
    font-weight: bold;
    border-bottom: 0.2em solid var(--color-box);
    text-transform: uppercase;
    padding-left: 15%;
    padding-top: 0.4em;
    position: relative; /* ancre pour le ::before */
}

/* Style de base pour le compteur numérique */
.rule-title::before {
    content: '';
    font-size: 1.2em;
    font-weight: bold;
    display: flex;
    align-items: center;
    justify-content: center;
    position: absolute;
    color: #fff;
    left: 1.7em;
    top: 50%;
    transform: translateY(-50%);
    background-color: var(--color-box);
    width: 2.5em;
    height: 2.5em;
}

/* Contenu des compteurs */
.rule-counter-0::before { content: '01'; }
.rule-counter-1::before { content: '02'; }
.rule-counter-2::before { content: '03'; }
.rule-counter-3::before { content: '04'; }
.rule-counter-4::before { content: '05'; }


